mapper.select:
SELECT hrd.bpm
FROM health_data hd
         LEFT JOIN heart_rate_data hrd ON hd.record_id = hrd.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'HEART_RATE'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'HEART_RATE'
);

SELECT bod.spo2
FROM health_data hd
         LEFT JOIN blood_oxygen_data bod ON hd.record_id = bod.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'BLOOD_OXYGEN'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'BLOOD_OXYGEN'
);

SELECT rd.rpm,hd.record_id
FROM health_data hd
         LEFT JOIN respiration_data rd ON hd.record_id = rd.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'RESPIRATION'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'RESPIRATION'
);

SELECT SUM(sd.steps) AS steps
FROM health_data hd
         LEFT JOIN step_data sd ON hd.record_id = sd.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'STEPS'
  AND DATE(hd.created_at) = (
    SELECT DATE(MAX(created_at))
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'STEPS'
);

SELECT ROUND(SUM(sd.duration_min) / 60, 2) AS hours
FROM health_data hd
         JOIN sleep_data sd ON hd.record_id = sd.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'SLEEP'
  AND DATE(hd.created_at) = (
    SELECT DATE(MAX(created_at))
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'SLEEP'
);

SELECT bp.systolic, bp.diastolic
FROM health_data hd
         JOIN blood_pressure_data bp ON hd.record_id = bp.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'BLOOD_PRESSURE'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'BLOOD_PRESSURE'
);

SELECT bg.glucose_mmol mmol
FROM health_data hd
         JOIN glucose_data bg ON hd.record_id = bg.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'BLOOD_GLUCOSE'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'BLOOD_GLUCOSE'
);

SELECT ua.uric_acid_umol umol
FROM health_data hd
         JOIN uric_acid_data ua ON hd.record_id = ua.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'URIC_ACID'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'URIC_ACID'
);

SELECT ROUND(sd.distance_m / 1000, 2) AS distance,sd.calories
FROM health_data hd
         LEFT JOIN step_data sd ON hd.record_id = sd.record_id
WHERE hd.user_id = #{userId}
  AND hd.data_type = 'STEPS'
  AND hd.created_at = (
    SELECT MAX(created_at)
    FROM health_data
    WHERE user_id = #{userId}
      AND data_type = 'STEPS'
);

SELECT user_id userId, targetstep
FROM target_step
WHERE user_id = #{userId}

SELECT user_id userId, sporttime
FROM sport_time_data
WHERE user_id = #{userId}

SELECT user_id userId, targetheat TargetHeat
FROM target_heat_data
WHERE user_id = #{userId}
